				&& this.strategy.getText().length() > 0) {

			double progressInPart = (double) this.getProgressPosition()
					/ (double) this.strategy.getText().length();

			if (strategy.getText().length() > 0 && strategy.isAtEnd()) {
				progressInPart = 1d;
